using System;using System.Linq;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;
public static class FixWood161{
 const string W="Assets/Prefabs/Workshop/";
 static void Rec(UnityEngine.Object o){EditorUtility.SetDirty(o);PrefabUtility.RecordPrefabInstancePropertyModifications(o);}
 static Transform Home(GameObject r)=>r.GetComponentsInChildren<Transform>(true).First(t=>t.name=="Stone_House_Open_Entrance");
 static void Wood(GameObject root){var h=Home(root);var src=AssetDatabase.LoadAssetAtPath<GameObject>(W+"WoodenCottage_01.prefab");var wood=AssetDatabase.LoadAssetAtPath<Material>(W+"CottageGeometry/Roof_WarmBrown.mat");var dark=AssetDatabase.LoadAssetAtPath<Material>(W+"CottageGeometry/Roof_InteriorBrown.mat");foreach(var mf in h.Find("02_Walls").GetComponentsInChildren<MeshFilter>()){
 if(mf.name=="Transparent_Glass")continue;
 if(mf.name=="StoneWall"||mf.name=="StoneWallWindowShutters"){var name=mf.name=="StoneWall"?"wallWood":"wallWoodWindowShutters";var source=src.transform.Find("02_Walls").GetComponentsInChildren<MeshFilter>().First(t=>t.name==name);mf.sharedMesh=source.sharedMesh;Rec(mf);var rr=mf.GetComponent<Renderer>();rr.sharedMaterials=Enumerable.Range(0,mf.sharedMesh.subMeshCount).Select(i=>i==0?dark:wood).ToArray();Rec(rr);var mc=mf.GetComponent<MeshCollider>();if(mc){mc.sharedMesh=mf.sharedMesh;Rec(mc);}}
 else {var rr=mf.GetComponent<Renderer>();rr.sharedMaterials=rr.sharedMaterials.Select((m,i)=>i==0?dark:wood).ToArray();Rec(rr);}}
 foreach(var r in h.Find("03_Frame").GetComponentsInChildren<Renderer>()){r.sharedMaterials=r.sharedMaterials.Select((m,i)=>i==0?dark:wood).ToArray();Rec(r);}
 foreach(var r in h.Find("04_Roof").GetComponentsInChildren<Renderer>().Where(r=>r.name.IndexOf("Gable",StringComparison.OrdinalIgnoreCase)>=0)){r.sharedMaterials=r.sharedMaterials.Select(_=>wood).ToArray();Rec(r);}}
 public static string Main(){var log=new System.Text.StringBuilder();foreach(var n in new[]{"House1_1_OpenCourtyard","House1_3_GreenCourtyard"}){string path=W+"Locations/"+n+".prefab";var root=PrefabUtility.LoadPrefabContents(path);try{var shed=root.transform.Find("Open_Timber_LeanTo");var roof=shed.Find("Slate_Canopy");var normal=roof.localRotation*Vector3.up;Func<Vector3,float> underside=p=>roof.localPosition.y-(normal.x*(p.x-roof.localPosition.x)+normal.z*(p.z-roof.localPosition.z)+roof.localScale.y*.5f)/normal.y;foreach(Transform t in shed){if(t.name=="Timber_Post"){var p=t.localPosition;float bottom=p.y-t.localScale.y*.5f,top=underside(p)+.025f;var scale=t.localScale;scale.y=top-bottom;t.localScale=scale;p.y=(top+bottom)*.5f;t.localPosition=p;Rec(t);}if(t.name=="Timber_Beam"){var p=t.localPosition;p.y=underside(p)-t.localScale.y*.5f+.02f;t.localPosition=p;t.localRotation=roof.localRotation;Rec(t);}}if(!PrefabUtility.SaveAsPrefabAsset(root,path))throw new Exception(path);log.AppendLine(n+": roof supports joined");}finally{PrefabUtility.UnloadPrefabContents(root);}}
 foreach(var path in new[]{"Assets/Prefabs/Locations/Enemy/house2_1.prefab","Assets/Prefabs/Locations/Enemy/house2_2.prefab",W+"Locations/House1_2_LocationVariant.prefab"}){var r=PrefabUtility.LoadPrefabContents(path);try{Wood(r);if(!PrefabUtility.SaveAsPrefabAsset(r,path))throw new Exception(path);log.AppendLine(path+": wooden meshes and trim");}finally{PrefabUtility.UnloadPrefabContents(r);}}
 var s=SceneManager.GetSceneByPath("Assets/Scenes/House1VariantsWorkshop.unity");if(s.isLoaded)EditorSceneManager.SaveScene(s);AssetDatabase.SaveAssets();return log.ToString();}
}

